package quicktunnelauth

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestNewQuickTunnelAuthRecipientPolicy(t *testing.T) {
	t.Parallel()

	policy, err := NewQuickTunnelAuthRecipientPolicy([]string{
		"Visitor@Example.com",
		"*@Allowed.example",
	})
	require.NoError(t, err)

	tests := []struct {
		name    string
		email   string
		allowed bool
	}{
		{name: "exact", email: "visitor@example.com", allowed: true},
		{name: "normalized exact", email: " Visitor@Example.com ", allowed: true},
		{name: "wildcard domain", email: "other@allowed.example", allowed: true},
		{name: "wildcard does not include subdomains", email: "other@sub.allowed.example"},
		{name: "wildcard rejects empty local part", email: "@allowed.example"},
		{name: "different address", email: "other@example.com"},
		{name: "invalid address", email: "not-an-email"},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()
			assert.Equal(t, test.allowed, policy.allows(test.email))
		})
	}
}

func TestQuickTunnelAuthRecipientPolicyAllowedRecipientCounts(t *testing.T) {
	t.Parallel()

	policy, err := NewQuickTunnelAuthRecipientPolicy([]string{
		"visitor@example.com",
		"Visitor@Example.com",
		"other@example.com",
		"*@allowed.example",
	})
	require.NoError(t, err)

	emailAddresses, emailDomains := policy.AllowedRecipientCounts()
	assert.Equal(t, 2, emailAddresses)
	assert.Equal(t, 1, emailDomains)

	var nilPolicy *QuickTunnelAuthRecipientPolicy
	emailAddresses, emailDomains = nilPolicy.AllowedRecipientCounts()
	assert.Zero(t, emailAddresses)
	assert.Zero(t, emailDomains)
}

func TestNewQuickTunnelAuthRecipientPolicyRejectsInvalidRules(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name   string
		values []string
	}{
		{name: "missing"},
		{name: "empty", values: []string{""}},
		{name: "invalid", values: []string{"not-an-email"}},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()
			policy, err := NewQuickTunnelAuthRecipientPolicy(test.values)
			require.Error(t, err)
			assert.Nil(t, policy)
		})
	}
}

package quicktunnelauth

import (
	"fmt"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestValidateQuickTunnelAllowedMail(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name            string
		values          []string
		expectedEmails  []string
		expectedDomains []string
	}{
		{name: "multiple without spaces", values: []string{"one@example.com,two@example.com"}, expectedEmails: []string{"one@example.com", "two@example.com"}},
		{name: "multiple with consistent spaces", values: []string{"one@example.com, two@example.com"}, expectedEmails: []string{"one@example.com", "two@example.com"}},
		{name: "multiple with inconsistent spaces", values: []string{" one@Example.com,two@example.com , THREE@example.com "}, expectedEmails: []string{"one@example.com", "two@example.com", "three@example.com"}},
		{name: "single with leading spaces", values: []string{" user@example.com"}, expectedEmails: []string{"user@example.com"}},
		{name: "single with trailing spaces", values: []string{"user@example.com "}, expectedEmails: []string{"user@example.com"}},
		{name: "single with surrounding spaces", values: []string{" User@Example.com "}, expectedEmails: []string{"user@example.com"}},
		{name: "repeated flags", values: []string{"first@example.com", "second@example.net,*@Example.org"}, expectedEmails: []string{"first@example.com", "second@example.net"}, expectedDomains: []string{"example.org"}},
		{name: "deduplicated", values: []string{"User@example.com,user@example.com", "*@Example.org,*@example.org"}, expectedEmails: []string{"user@example.com"}, expectedDomains: []string{"example.org"}},
		{name: "punycode IDN", values: []string{"jim@something.xn--fiqs8s,*@xn--fiqs8s"}, expectedEmails: []string{"jim@something.xn--fiqs8s"}, expectedDomains: []string{"xn--fiqs8s"}},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()

			emails, domains, err := validateQuickTunnelAllowedMail(test.values)
			require.NoError(t, err)
			assert.Len(t, emails, len(test.expectedEmails))
			assert.Len(t, domains, len(test.expectedDomains))
			for _, email := range test.expectedEmails {
				assert.Contains(t, emails, email)
			}
			for _, domain := range test.expectedDomains {
				assert.Contains(t, domains, domain)
			}
		})
	}
}

func TestValidateQuickTunnelAllowedMailRejectsMalformedEntries(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name   string
		values []string
	}{
		{name: "empty"},
		{name: "blank", values: []string{" , "}},
		{name: "display name", values: []string{"User <user@example.com>"}},
		{name: "missing wildcard at", values: []string{"*example.com"}},
		{name: "double at", values: []string{"user@@example.com"}},
		{name: "invalid exact domain", values: []string{"user@-example.com"}},
		{name: "empty wildcard domain", values: []string{"*@"}},
		{name: "empty domain label", values: []string{"*@example..com"}},
		{name: "leading domain hyphen", values: []string{"*@-example.com"}},
		{name: "trailing domain hyphen", values: []string{"*@example-.com"}},
		{name: "invalid domain character", values: []string{"*@exam_ple.com"}},
		{name: "unicode IDN", values: []string{"jim@something.\u4e2d\u56fd"}},
		{name: "long domain label", values: []string{"*@" + strings.Repeat("a", 64) + ".com"}},
		{name: "long domain", values: []string{"*@" + strings.Repeat("a.", 126) + "aa"}},
		{name: "domain path", values: []string{"*@example.com/path"}},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()
			_, _, err := validateQuickTunnelAllowedMail(test.values)
			require.Error(t, err)
		})
	}
}

func TestValidateQuickTunnelAllowedMailRejectsEmptyRuleWithoutLeakingValues(t *testing.T) {
	t.Parallel()

	values := []string{"first@example.com,,second@example.com"}
	_, _, err := validateQuickTunnelAllowedMail(values)
	require.EqualError(t, err, "allowed mail rule 2 is empty")
	assert.NotContains(t, err.Error(), "example.com")
}

func TestValidateQuickTunnelAllowedMailReportsInvalidRule(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name          string
		values        []string
		expectedError string
	}{
		{name: "email", values: []string{"first@example.com", "private@example.com/path"}, expectedError: "allowed mail rule 2 is not a valid email address"},
		{name: "wildcard", values: []string{"first@example.com", "*@example.com/path"}, expectedError: "allowed mail rule 2 has an invalid wildcard domain"},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()
			_, _, err := validateQuickTunnelAllowedMail(test.values)
			require.EqualError(t, err, test.expectedError)
			for _, value := range test.values {
				assert.NotContains(t, err.Error(), value)
			}
		})
	}
}

func TestValidateQuickTunnelAllowedMailBoundsInput(t *testing.T) {
	t.Parallel()

	tooManyRules := make([]string, quickTunnelAuthMaxAllowedMailRules+1)
	for index := range tooManyRules {
		tooManyRules[index] = "user@example.com"
	}
	tests := []struct {
		name          string
		values        []string
		expectedError string
	}{
		{
			name:          "too many rules",
			values:        tooManyRules,
			expectedError: fmt.Sprintf("allowed mail rules exceed the %d-entry limit", quickTunnelAuthMaxAllowedMailRules),
		},
		{
			name:          "rule too long before trimming",
			values:        []string{strings.Repeat(" ", quickTunnelAuthMaxAllowedMailRuleBytes) + "a"},
			expectedError: fmt.Sprintf("allowed mail rule 1 exceeds the %d-byte limit", quickTunnelAuthMaxAllowedMailRuleBytes),
		},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			t.Parallel()
			_, _, err := validateQuickTunnelAllowedMail(test.values)
			require.EqualError(t, err, test.expectedError)
		})
	}
}

package quicktunnelauth

import (
	"errors"
	"fmt"
	"strings"
)

// QuickTunnelAuthRecipientPolicy contains normalized, process-local recipient
// rules for one protected Quick Tunnel.
type QuickTunnelAuthRecipientPolicy struct {
	emails          map[string]struct{}
	wildcardDomains map[string]struct{}
}

// NewQuickTunnelAuthRecipientPolicy validates and normalizes allowed email and
// wildcard-domain rules.
func NewQuickTunnelAuthRecipientPolicy(values []string) (*QuickTunnelAuthRecipientPolicy, error) {
	if len(values) == 0 {
		return nil, errors.New("at least one allowed mail rule is required")
	}

	emails, wildcardDomains, err := validateQuickTunnelAllowedMail(values)
	if err != nil {
		return nil, fmt.Errorf("validate allowed mail rules: %w", err)
	}
	return &QuickTunnelAuthRecipientPolicy{
		emails:          emails,
		wildcardDomains: wildcardDomains,
	}, nil
}

// AllowedRecipientCounts returns the number of exact email addresses and
// wildcard-domain rules without exposing the configured recipients.
func (p *QuickTunnelAuthRecipientPolicy) AllowedRecipientCounts() (emailAddresses, emailDomains int) {
	if p == nil {
		return 0, 0
	}
	return len(p.emails), len(p.wildcardDomains)
}

func (p *QuickTunnelAuthRecipientPolicy) allows(email string) bool {
	if p == nil {
		return false
	}

	normalizedEmail := normalizeQuickTunnelEmail(email)
	if !isValidQuickTunnelEmail(normalizedEmail) {
		return false
	}

	if _, ok := p.emails[normalizedEmail]; ok {
		return true
	}
	_, domain, _ := strings.Cut(normalizedEmail, "@")
	_, ok := p.wildcardDomains[domain]
	return ok
}

