		{name: "encoded backslash", rawPath: "/dashboard%5Clogs"},
		{name: "callback path", rawPath: QuickTunnelAuthCallbackPath},
		{name: "callback path with query", rawPath: QuickTunnelAuthCallbackPath + "?state=value"},
